using namespace up;
namespace {
unsigned checks;
void verify(bool ok,const char* text){++checks;if(!ok){std::fprintf(stderr,"FAIL HOLES: %s\n",text);std::exit(1);}}
bool near(float a,float b,float epsilon=.001f){return std::fabs(a-b)<epsilon;}
void arena(Game& g,unsigned skip=0){g=Game();g.phase=Phase::Aiming;g.target=1000000;g.world.pockets_enabled=false;Ball cue;cue.cue=true;cue.p=Vec(0,300);g.world.add(cue);g.set_run_seed(0x554c5452u+skip*7919u);g.snacks={};g.actions={};}
unsigned add(Game& g,BallKey key,Vec position=Vec(),unsigned level=1,int value=1){Ball b;b.def=builtin(id_of(key));b.def.base_score=value;b.level=static_cast<uint8_t>(level);b.p=position;g.world.add(b);return g.world.last_added;}
void pocket(Game& g,unsigned index,unsigned id=6){g.world.balls[index].active=false;g.world.balls[index].v=Vec();++g.world.metrics.ticks;g.world.events.push(EventKind::Pocketed,index,id,g.world.metrics.ticks,g.world.balls[index].generation);g.dispatch();}
void resolve(Game& g){for(unsigned i=0;i<2400 && g.pending_actions();++i)g.update(tick_dt);verify(!g.pending_actions(),"pocket carriers finish");}
}
